describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -10, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1_000, costCents: 600 },
      { upToGrams: 5_000, costCents: 1_200 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1_000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      expect(calc.computeShippingCents([line("a", 500, 2)], 1_000)).toBe(0);
    });

    it("selects the first bracket matching the weight", () => {
      // 200g × 2 = 400g → 500g bracket = 300
      expect(
        calc.computeShippingCents([line("a", 500, 2, 200)], 1_000),
      ).toBe(300);
    });

    it("selects the bracket at exact boundary", () => {
      // 500g exactly → 500g bracket = 300
      expect(
        calc.computeShippingCents([line("a", 500, 1, 500)], 1_000),
      ).toBe(300);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      // 501g → next bracket (1000g) = 600
      expect(
        calc.computeShippingCents([line("a", 500, 1, 501)], 1_000),
      ).toBe(600);
    });

    it("selects the heaviest bracket boundary", () => {
      // 5000g exactly → 5000g bracket = 1200
      expect(
        calc.computeShippingCents([line("a", 500, 1, 5000)], 1_000),
      ).toBe(1_200);
    });

    it("uses heaviest bracket cost when overflowing without overflowCostCents", () => {
      // 5001g → overflow, no overflow cost → use last bracket = 1200
      expect(
        calc.computeShippingCents([line("a", 500, 1, 5001)], 1_000),
      ).toBe(1_200);
    });

    it("uses overflowCostCents when configured and weight overflows", () => {
      const withOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 1_000, costCents: 600 },
        ],
        2_000,
      );
      // 1500g → overflow → 2000
      expect(
        withOverflow.computeShippingCents([line("a", 500, 1, 1500)], 1_000),
      ).toBe(2_000);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1_000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → 500g bracket = 300
      expect(
        unordered.computeShippingCents([line("a", 500, 1, 400)], 1_000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const lines: CartLine[] = [
        line("a", 500, 2, 300), // 600g
        line("b", 500, 1, 500), // 500g → total 1100g
      ];
      // 1100g → 5000g bracket = 1200
      expect(calc.computeShippingCents(lines, 1_000)).toBe(1_200);
    });
  });
});

