import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  price: number,
  weight?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities for the same product", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 2);
      cart.add(product("a", 500), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 500), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 500), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 500), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -100), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("unknown")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 500), 2);
      cart.add(product("b", 300), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      const cart = new Cart();
      const p = product("a", 500);
      cart.add(p, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);
      // Mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price × quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1_000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3_500);
    });

    it("applies default policies (no discount, no tax, free shipping)", () => {
      const cart = new Cart();
      cart.add(product("a", 1_000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1_000);
    });

    it("returns zeroes for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps discount to [0, subtotal]", () => {
      const excessDiscount: DiscountPolicy = {
        computeDiscountCents: () => 99_999,
      };
      const cart = new Cart({ discountPolicy: excessDiscount });
      cart.add(product("a", 1_000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1_000);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negativeDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negativeDiscount });
      cart.add(product("a", 1_000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on the discounted subtotal", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: (sub) => Math.floor(sub * 0.1),
      };
      const tax: TaxCalculator = {
        computeTaxCents: (taxable, _region) => Math.floor(taxable * 0.08),
      };
      const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
      cart.add(product("a", 10_000), 1);
      const totals = cart.totals();
      // subtotal 10000, discount 1000, taxable 9000, tax 720
      expect(totals.subtotalCents).toBe(10_000);
      expect(totals.discountCents).toBe(1_000);
      expect(totals.taxCents).toBe(720);
    });

    it("passes discounted subtotal to shipping calculator", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 2_000,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: (_lines, subtotalCents) => {
          // Free if discounted subtotal ≥ 5000
          return subtotalCents >= 5_000 ? 0 : 500;
        },
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 8_000), 1);
      const totals = cart.totals();
      // discounted subtotal = 6000 ≥ 5000 → free
      expect(totals.shippingCents).toBe(0);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const tax: TaxCalculator = {
        computeTaxCents: () => 200,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 100,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 2_000), 1);
      const totals = cart.totals();
      // subtotal=2000, discount=500, discounted=1500, tax=200, shipping=100
      // total = 1500 + 200 + 100 = 1800
      expect(totals.totalCents).toBe(1_800);
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 1_000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => -50,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 1_000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("uses the configured region for tax", () => {
      const regionSpy = vi.fn().mockReturnValue(100);
      const tax: TaxCalculator = {
        computeTaxCents: regionSpy,
      };
      const cart = new Cart({ taxCalculator: tax, region: "FR" });
      cart.add(product("a", 1_000), 1);
      cart.totals();
      expect(regionSpy).toHaveBeenCalledWith(1_000, "FR");
    });

    it("defaults region to US", () => {
      const regionSpy = vi.fn().mockReturnValue(0);
      const tax: TaxCalculator = { computeTaxCents: regionSpy };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 1_000), 1);
      cart.totals();
      expect(regionSpy).toHaveBeenCalledWith(1_000, "US");
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for a simple checkout", async () => {
      const cart = new Cart();
      cart.add(product("a", 1_000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2_000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product("a", 1_000), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1_500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(3_000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1_500);
    });

    it("throws InventoryError when inventory check fails", async () => {
      const cart = new Cart();
      cart.add(product("a", 1_000), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
        expect(invErr.message).toBe("low stock");
      }
    });

    it("throws InventoryError for partial-stock denial (available < requested)", async () => {
      const cart = new Cart();
      cart.add(product("a", 1_000), 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("passes inventory check when sufficient stock", async () => {
      const cart = new Cart();
      cart.add(product("a", 1_000), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 10,
        }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2_000);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 200,
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(product("a", 5_000), 1);
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=5000, discount=500, discounted=4500, tax=450, shipping=200
      expect(result.totals.subtotalCents).toBe(5_000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(450);
      expect(result.totals.shippingCents).toBe(200);
      expect(result.totals.totalCents).toBe(5_150);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(product("a", 1_000), 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
      const cart = new Cart({ region: "FR" });
      cart.add(product("a", 1_000), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1_200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // Refreshed price: 1200, qty 2 → subtotal 2400, no discount → tax 20% of 2400 = 480
      expect(result.totals.subtotalCents).toBe(2_400);
      expect(result.totals.taxCents).toBe(480);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1_200);
    });

    it("generates a default message for inventory denial without reason", async () => {
      const cart = new Cart();
      cart.add(product("x", 1_000), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("insufficient stock");
        expect(invErr.message).toContain("x");
        expect(invErr.available).toBe(0);
      }
    });

    it("checkout without collaborators uses sync totals", async () => {
      const tax: TaxCalculator = {
        computeTaxCents: () => 100,
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 1_000), 1);
      const result = await cart.checkout({});
      expect(result.totals.taxCents).toBe(100);
    });
  });
});

